function getSpeechRecognitionConstructor() {
  if (typeof window === 'undefined') {
    return null;
  }

  return (
    window.SpeechRecognition ||
    window.webkitSpeechRecognition ||
    null
  );
}

export function isSpeechRecognitionSupported() {
  return (
    typeof window !== 'undefined' &&
    ('SpeechRecognition' in window ||
      'webkitSpeechRecognition' in window)
  );
}

export function createRecognizer({
  lang = 'en-AU',
  interimResults = true,
  continuous = false,
} = {}) {
  if (!isSpeechRecognitionSupported()) {
    return null;
  }

  const SpeechRecognition =
    window.SpeechRecognition ||
    window.webkitSpeechRecognition;

  const recognizer =
    new SpeechRecognition();

  recognizer.lang = lang;
  recognizer.interimResults =
    interimResults;
  recognizer.continuous =
    continuous;
  recognizer.maxAlternatives = 1;

  return recognizer;
}

export function isSpeechSynthesisSupported() {
  return (
    typeof window !== 'undefined' &&
    'speechSynthesis' in window
  );
}

// --- Speech output (new) -----------------------------------------------
// Mirrors the createRecognizer pattern: this module holds no conversation
// state, just a thin wrapper around the browser API. The calling hook
// owns state (speaking/idle/etc). Only one utterance is ever "current" —
// starting a new one implicitly cancels any speech in progress, which is
// also what backs the barge-in behaviour (tap mic while speaking -> stop).

let currentUtterance = null;

export function speak(text, { lang = 'en-AU', rate = 1, pitch = 1, onStart, onEnd, onError } = {}) {
  if (!isSpeechSynthesisSupported() || !text) {
    onError?.('unsupported');
    return null;
  }

  // Cancel any in-flight utterance before starting the next one, so calls
  // never queue up and talk over each other.
  window.speechSynthesis.cancel();

  const utterance = new SpeechSynthesisUtterance(text);
  utterance.lang = lang;
  utterance.rate = rate;
  utterance.pitch = pitch;

  utterance.onstart = () => onStart?.();

  utterance.onend = () => {
    if (currentUtterance === utterance) currentUtterance = null;
    onEnd?.();
  };

  utterance.onerror = (event) => {
    if (currentUtterance === utterance) currentUtterance = null;
    // "interrupted" and "canceled" fire from our own cancelSpeech()/barge-in
    // calls — that's expected, not a real error, so don't surface it as one.
    if (event.error === 'interrupted' || event.error === 'canceled') {
      onEnd?.();
      return;
    }
    onError?.(event.error);
  };

  currentUtterance = utterance;
  window.speechSynthesis.speak(utterance);

  return utterance;
}

export function cancelSpeech() {
  if (!isSpeechSynthesisSupported()) return;
  window.speechSynthesis.cancel();
  currentUtterance = null;
}

export default {
  isSpeechRecognitionSupported,
  createRecognizer,
  isSpeechSynthesisSupported,
  speak,
  cancelSpeech,
};
